#!/usr/bin/env python3
"""
Reproduction script for the issue where yamllint and ansible-lint 
are incorrectly removed by ansible-builder introspect --sanitize
"""

from ansible_builder.requirements import sanitize_requirements

def test_yamllint_ansible_lint_removed_issue():
    """Test that demonstrates the issue where yamllint and ansible-lint are removed"""

    # Simulate a user's requirements.txt that includes yamllint and ansible-lint
    user_requirements = {
        'user': [
            'yamllint>=1.26.0',
            'ansible-lint>=5.0.0',
            'requests>=2.25.0',  # This should remain
            'ansible-core>=2.11.0'  # This should be removed (legitimate exclusion)
        ]
    }

    print("Original requirements:")
    for req in user_requirements['user']:
        print(f"  {req}")

    # Apply sanitization (what happens during ansible-builder introspect --sanitize)
    sanitized = sanitize_requirements(user_requirements)

    print("\nAfter sanitization:")
    for req in sanitized:
        print(f"  {req}")

    # Check what happened
    sanitized_packages = [line.split()[0] for line in sanitized]

    print(f"\nPackages after sanitization: {sanitized_packages}")

    # The issue: yamllint and ansible-lint should NOT be removed
    if 'yamllint' in sanitized_packages:
        print("✓ yamllint correctly preserved")
    else:
        print("✗ ISSUE: yamllint was incorrectly removed!")

    if 'ansible-lint' in sanitized_packages:
        print("✓ ansible-lint correctly preserved")  
    else:
        print("✗ ISSUE: ansible-lint was incorrectly removed!")

    # ansible-core should be removed (this is correct behavior)
    if 'ansible-core' not in sanitized_packages:
        print("✓ ansible-core correctly removed (expected)")
    else:
        print("? ansible-core was preserved (unexpected but not necessarily wrong)")

    # requests should be preserved (this is correct behavior)
    if 'requests' in sanitized_packages:
        print("✓ requests correctly preserved")
    else:
        print("✗ ERROR: requests was incorrectly removed!")

    return sanitized_packages

if __name__ == "__main__":
    print("=== Reproducing the yamllint/ansible-lint removal issue ===")
    result = test_yamllint_ansible_lint_removed_issue()

    print(f"\n=== Summary ===")
    has_issue = ('yamllint' not in result) or ('ansible-lint' not in result)
    if has_issue:
        print("ISSUE CONFIRMED: yamllint and/or ansible-lint are being incorrectly removed")
    else:
        print("ISSUE NOT FOUND: Both packages are correctly preserved")

#!/usr/bin/env python3
"""
Debug script to understand how requirements parsing works
"""

import requirements
from ansible_builder.requirements import sanitize_requirements

def debug_requirements_parsing():
    """Debug how requirements are parsed"""

    lines = [
        'yamllint>=1.26.0',
        'ansible-lint>=5.0.0', 
        'requests>=2.25.0',
        'ansible-core>=2.11.0'
    ]

    print("Raw lines:")
    for line in lines:
        print(f"  {line}")

    print("\nParsing with requirements library:")
    for line in lines:
        try:
            reqs = list(requirements.parse(line))
            for req in reqs:
                print(f"  Line: '{line}' -> Name: '{req.name}', Specs: {req.specs}")
        except Exception as e:
            print(f"  Line: '{line}' -> ERROR: {e}")

def debug_sanitize_step_by_step():
    """Debug the sanitize process step by step"""

    user_requirements = {
        'user': [
            'yamllint>=1.26.0',
            'ansible-lint>=5.0.0',
            'requests>=2.25.0',
        ]
    }

    print("\n=== Debug sanitize_requirements ===")
    print("Input:", user_requirements)

    # de-duplication part
    consolidated = []
    seen_pkgs = set()
    for collection, lines in user_requirements.items():
        print(f"Processing collection: {collection}")
        try:
            for req in requirements.parse('\n'.join(lines)):
                print(f"  Parsed req: name='{req.name}', line='{req.line}'")
                req.collections = [collection]  # add backref for later
                if req.name is None:
                    consolidated.append(req)
                    continue
                if req.name in seen_pkgs:
                    print(f"    Duplicate: {req.name}")
                    for prior_req in consolidated:
                        if req.name == prior_req.name:
                            prior_req.specs.extend(req.specs)
                            prior_req.collections.append(collection)
                            break
                    continue
                consolidated.append(req)
                seen_pkgs.add(req.name)
                print(f"    Added: {req.name} -> {seen_pkgs}")
        except Exception as e:
            print(f"    Error parsing: {e}")

    print(f"\nConsolidated requirements ({len(consolidated)} items):")
    for req in consolidated:
        print(f"  Name: {req.name}, Collections: {getattr(req, 'collections', 'N/A')}")

    # removal of unwanted packages
    from ansible_builder.requirements import EXCLUDE_REQUIREMENTS
    print(f"\nEXCLUDE_REQUIREMENTS: {EXCLUDE_REQUIREMENTS}")

    sanitized = []
    for req in consolidated:
        print(f"Checking {req.name}...")
        if req.name and req.name.lower() in EXCLUDE_REQUIREMENTS:
            print(f"  EXCLUDED: {req.name}")
            continue
        print(f"  KEPT: {req.name}")
        sanitized.append(req)

    print(f"\nFinal sanitized count: {len(sanitized)}")
    return sanitized

if __name__ == "__main__":
    debug_requirements_parsing()
    debug_sanitize_step_by_step()

