#!/usr/bin/env python3
"""
Test edge cases to ensure the fix doesn't break existing functionality
"""

from ansible_builder.requirements import sanitize_requirements

def test_edge_cases():
    """Test various edge cases to ensure existing functionality still works"""

    test_cases = [
        {
            'name': 'Basic case with yamllint/ansible-lint preserved',
            'input': {
                'user': ['yamllint>=1.26.0', 'ansible-lint>=5.0.0', 'requests>=2.25.0']
            },
            'should_preserve': ['yamllint', 'ansible-lint', 'requests'],
            'should_exclude': []
        },
        {
            'name': 'Still exclude truly unwanted packages',
            'input': {
                'user': ['ansible-core>=2.11.0', 'pytest>=6.0.0', 'tox>=3.0.0', 'requests>=2.25.0']
            },
            'should_preserve': ['requests'],
            'should_exclude': ['ansible-core', 'pytest', 'tox']
        },
        {
            'name': 'Mixed case with duplicates',
            'input': {
                'col1': ['yamllint>=1.26.0', 'requests>=2.25.0'],
                'col2': ['ansible-lint>=5.0.0', 'requests>=2.20.0']
            },
            'should_preserve': ['yamllint', 'ansible-lint', 'requests'],
            'should_exclude': []
        }
    ]

    all_passed = True

    for test_case in test_cases:
        print(f"\n=== {test_case['name']} ===")
        print("Input:", test_case['input'])

        sanitized_lines = sanitize_requirements(test_case['input'])
        print("Output:")
        for line in sanitized_lines:
            print(f"  {line}")

        # Extract package names
        sanitized_packages = []
        for line in sanitized_lines:
            package_part = line.split('#')[0].strip()
            package_name = package_part.split('>')[0].split('<')[0].split('=')[0].split('!')[0].split('~')[0].strip()
            sanitized_packages.append(package_name)

        print(f"Packages: {sanitized_packages}")

        # Check preserved packages
        for pkg in test_case['should_preserve']:
            if pkg in sanitized_packages:
                print(f"✓ {pkg} correctly preserved")
            else:
                print(f"✗ ERROR: {pkg} should be preserved but was removed")
                all_passed = False

        # Check excluded packages  
        for pkg in test_case['should_exclude']:
            if pkg not in sanitized_packages:
                print(f"✓ {pkg} correctly excluded")
            else:
                print(f"✗ ERROR: {pkg} should be excluded but was preserved")
                all_passed = False

    return all_passed

if __name__ == "__main__":
    print("=== Testing Edge Cases ===")
    success = test_edge_cases()

    if success:
        print("\n✓ All edge case tests passed!")
    else:
        print("\n✗ Some edge case tests failed!")

